export interface GoogleCalendarConfig {
  /** Stable, non-secret label for one OAuth installation. */
  sourceId: string
  /** Journal identities use this prefix; change it for a separate installation. */
  streamPrefix: string
  calendarId: string
  database: string
  maxChunks: number
}

/** Runtime settings; the exported destination schemas use database at setup time. */
export type GoogleCalendarReaderConfig = Omit<GoogleCalendarConfig, 'database'>

// Set schema placement before importing index.ts. Credentials are read at request time.
export const googleCalendarConfig: GoogleCalendarConfig = {
  sourceId: 'google-calendar.primary',
  streamPrefix: 'google-calendar',
  calendarId: 'primary',
  database: 'default',
  maxChunks: 200,
}

import { HttpError, IngestConfigError, type ErrorClassifier, type FetchContext } from '@chkit/plugin-ingest'

import { googleCalendarConfig, type GoogleCalendarReaderConfig } from './config.js'
import type { CalendarState } from './sources/events.js'

export interface CalendarEvent { id: string; [key: string]: unknown }
interface Page { items: CalendarEvent[]; nextPageToken?: string; nextSyncToken?: string }

export interface GoogleCalendarClientDeps {
  config: GoogleCalendarReaderConfig
  fetch: (url: string, init: RequestInit) => Promise<Response>
  token: () => string | undefined
}

export const defaultGoogleCalendarClientDeps: GoogleCalendarClientDeps = {
  config: googleCalendarConfig,
  fetch: (url, init) => fetch(url, init),
  token: () => process.env.GOOGLE_CALENDAR_ACCESS_TOKEN,
}

export const classifyGoogleCalendarError: ErrorClassifier = (cause) =>
  cause instanceof IngestConfigError || cause instanceof SyntaxError ? { kind: 'permanent' } : undefined

export async function resolveCalendar(context: FetchContext, deps: GoogleCalendarClientDeps): Promise<string> {
  return context.attempt(async (signal) => {
    const payload = await request(`calendars/${encodeURIComponent(deps.config.calendarId)}`, signal, deps)
    return requiredString(payload.id, 'calendar id')
  }, { label: 'GET calendar metadata' })
}

/** paginate owns the single executor attempt around this page request. */
export async function requestEvents(state: CalendarState, signal: AbortSignal, deps: GoogleCalendarClientDeps): Promise<Page | { reset: 'sync' | 'page' }> {
  const url = new URL(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(state.calendarId)}/events`)
  for (const [key, value] of Object.entries({ singleEvents: 'false', showDeleted: 'true', maxResults: '250' })) url.searchParams.set(key, value)
  if (state.syncToken) url.searchParams.set('syncToken', state.syncToken)
  if (state.pageToken) url.searchParams.set('pageToken', state.pageToken)
  const response = await deps.fetch(url.toString(), { signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), headers: authorization(deps), redirect: 'error' })
  if (response.status === 410 && state.syncToken) return { reset: 'sync' }
  if ((response.status === 400 || response.status === 410) && state.pageToken) return { reset: 'page' }
  if (!response.ok) throw await HttpError.fromResponse(response)
  const payload: unknown = await response.json()
  if (!isObject(payload) || (payload.items !== undefined && !Array.isArray(payload.items))) throw new IngestConfigError('Calendar items are not an array.')
  const items = (payload.items ?? []).map((item: unknown) => {
    if (!isObject(item)) throw new IngestConfigError('Calendar returned an invalid event.')
    return { ...item, id: requiredString(item.id, 'event id') }
  })
  const nextPageToken = optionalString(payload.nextPageToken, 'nextPageToken')
  const nextSyncToken = optionalString(payload.nextSyncToken, 'nextSyncToken')
  if (nextPageToken && nextSyncToken) throw new IngestConfigError('Calendar returned both a page and sync token.')
  if (!nextPageToken && !nextSyncToken) throw new IngestConfigError('Calendar terminal page has no nextSyncToken.')
  return { items, nextPageToken, nextSyncToken }
}

async function request(path: string, signal: AbortSignal, deps: GoogleCalendarClientDeps): Promise<Record<string, unknown>> {
  const response = await deps.fetch(`https://www.googleapis.com/calendar/v3/${path}`, { signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), headers: authorization(deps), redirect: 'error' })
  if (!response.ok) throw await HttpError.fromResponse(response)
  const payload: unknown = await response.json()
  if (!isObject(payload)) throw new IngestConfigError('Calendar returned an invalid response.')
  return payload
}

function authorization(deps: GoogleCalendarClientDeps): Record<string, string> {
  const token = deps.token()?.trim()
  if (!token) throw new IngestConfigError('Set GOOGLE_CALENDAR_ACCESS_TOKEN.')
  return { Authorization: `Bearer ${token}` }
}

export function optionalString(value: unknown, field: string): string | undefined {
  return value === undefined ? undefined : requiredString(value, field)
}

export function requiredString(value: unknown, field: string): string {
  if (typeof value !== 'string' || value.trim().length === 0) throw new IngestConfigError(`Calendar ${field} must be a non-empty string.`)
  return value
}

export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

import { cursorState, definePipeline, defineStream, IngestConfigError } from '@chkit/plugin-ingest'

import { classifyGoogleCalendarError, defaultGoogleCalendarClientDeps, type GoogleCalendarClientDeps } from './client.js'
import { googleCalendarConfig, type GoogleCalendarReaderConfig } from './config.js'
import { google_calendar_eventsRaw, parseCalendarState, readEvents, type CalendarState } from './sources/events.js'

export function createGoogleCalendarPipeline(config: GoogleCalendarReaderConfig = googleCalendarConfig, deps: GoogleCalendarClientDeps = defaultGoogleCalendarClientDeps) {
  const boundConfig = { ...config }
  if (!boundConfig.sourceId.trim() || !boundConfig.streamPrefix.trim() || !boundConfig.calendarId.trim()) throw new IngestConfigError('Calendar sourceId, streamPrefix and calendarId must be non-empty strings.')
  const client = { ...deps, config: boundConfig }
  return definePipeline({
    id: boundConfig.streamPrefix, tags: ['provider:google-calendar'], maxStreams: 1, maxFetches: 1,
    streams: [defineStream({
      id: `${boundConfig.streamPrefix}.events`, tags: ['resource:events'], destination: google_calendar_eventsRaw,
      incremental: {
        ...cursorState<CalendarState>({ id: `${boundConfig.streamPrefix}.sync-token`, version: 1, parse: (raw) => parseCalendarState(raw, boundConfig) }),
        plan({ state, range }) {
          if (range?.from || range?.to) throw new IngestConfigError('Calendar canonical sync does not accept date bounds. Use a separate bounded instances reader for an occurrence backfill.')
          return state
        },
      },
      batchSize: 1,
      budget: { maxChunks: boundConfig.maxChunks, maxChunkRows: 250 },
      classifyError: classifyGoogleCalendarError,
      read: (context) => readEvents(context, client),
    })],
  })
}

export const google_calendarPipeline = createGoogleCalendarPipeline()

import { IngestConfigError, paginate, rawRows, rawTable, type Page, type ReadContext } from '@chkit/plugin-ingest'

import { isObject, optionalString, requestEvents, requiredString, resolveCalendar, type CalendarEvent, type GoogleCalendarClientDeps } from '../client.js'
import { googleCalendarConfig, type GoogleCalendarReaderConfig } from '../config.js'

export interface CalendarState {
  scope: string
  calendarId: string
  syncToken?: string
  pageToken?: string
  /** Recovery attempts for this unfinished sync, including previous executions. */
  recoveryCount?: number
}

interface CalendarPageMetadata { checkpoint: CalendarState; id?: 'calendar-reset' | 'calendar-empty-page' }

export const google_calendar_eventsRaw = rawTable({ database: googleCalendarConfig.database, name: 'google_calendar_events_raw' })

// Candidate page state is acknowledged with its rows, including empty terminal pages.
export async function* readEvents(context: ReadContext<CalendarState | undefined, CalendarState>, deps: GoogleCalendarClientDeps) {
  const scope = calendarScope(deps.config)
  const sourceId = deps.config.sourceId
  const resolvedCalendarId = await resolveCalendar(context, deps)
  if (context.state && context.state.calendarId !== resolvedCalendarId) {
    throw new IngestConfigError('Calendar checkpoint belongs to a different authenticated calendar. Use a separate stream ID for the new source.')
  }
  const pages = paginate({
    context, initial: context.state ?? { scope, calendarId: resolvedCalendarId }, label: 'GET calendar events',
    fetchPage: async (cursor = { scope, calendarId: resolvedCalendarId }, signal): Promise<Page<CalendarEvent, CalendarState, CalendarPageMetadata>> => {
      const page = await requestEvents(cursor, signal, deps)
      if ('reset' in page) {
        if ((cursor.recoveryCount ?? 0) >= 1) throw new IngestConfigError('Calendar unfinished sync repeatedly rejected a token across resumed runs. Adjust the editable stream chunk budget, run duration, or polling frequency, then explicitly migrate the saved state or use a new stream identity after reviewing coverage.')
        // Reset debt distinguishes safe replay from cycling, and survives restarts.
        const checkpoint: CalendarState = { scope, calendarId: resolvedCalendarId, recoveryCount: 1, ...(page.reset === 'page' && cursor.syncToken ? { syncToken: cursor.syncToken } : {}) }
        return { items: [], next: checkpoint, metadata: { checkpoint, id: 'calendar-reset' } }
      }
      // Retain the input token on every continuation; only the terminal
      // checkpoint promotes nextSyncToken and clears recovery debt.
      const checkpoint: CalendarState = page.nextPageToken
        ? { ...cursor, pageToken: page.nextPageToken }
        : { scope, calendarId: resolvedCalendarId, syncToken: requiredString(page.nextSyncToken, 'nextSyncToken') }
      return { items: page.items, next: page.nextPageToken ? checkpoint : undefined,
        metadata: { checkpoint, ...(page.items.length === 0 ? { id: 'calendar-empty-page' } : {}) } }
    },
  })
  for await (const page of pages) {
    if (!page.metadata) throw new IngestConfigError('Calendar page has no checkpoint metadata.')
    yield { rows: rawRows(page.items, (event) => JSON.stringify([sourceId, resolvedCalendarId, event.id])),
      state: page.metadata.checkpoint, id: page.metadata.id }
  }
}

export function parseCalendarState(raw: unknown, config: GoogleCalendarReaderConfig): CalendarState {
  const scope = calendarScope(config)
  if (!isObject(raw) || raw.scope !== scope) throw new IngestConfigError('Calendar checkpoint scope changed. Migrate the state explicitly or use a new stream ID.')
  if (raw.recoveryCount !== undefined && raw.recoveryCount !== 0 && raw.recoveryCount !== 1) throw new IngestConfigError('Calendar checkpoint recoveryCount must be zero or one.')
  return { scope, calendarId: requiredString(raw.calendarId, 'checkpoint calendar id'), syncToken: optionalString(raw.syncToken, 'checkpoint syncToken'), pageToken: optionalString(raw.pageToken, 'checkpoint pageToken'), recoveryCount: raw.recoveryCount }
}

function calendarScope(config: GoogleCalendarReaderConfig): string {
  return JSON.stringify([config.sourceId, config.calendarId, { singleEvents: false, showDeleted: true, maxResults: 250 }])
}

import { afterEach, expect, test } from 'bun:test'
import { runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { google_calendarPipeline } from '../index.js'
import { googleCalendarConfig } from '../config.js'
import { createGoogleCalendarPipeline } from '../pipeline.js'

const originalFetch = globalThis.fetch
const originalToken = process.env.GOOGLE_CALENDAR_ACCESS_TOKEN

function setFetch(handler: (url: URL) => Response | Promise<Response>, calendar = () => 'calendar@example.com'): void {
  process.env.GOOGLE_CALENDAR_ACCESS_TOKEN = 'fixture'
  globalThis.fetch = Object.assign(async (input: Parameters<typeof fetch>[0]) => {
    const url = new URL(String(input))
    return url.pathname.endsWith('/events') ? handler(url) : Response.json({ id: calendar() })
  }, { preconnect: originalFetch.preconnect })
}

function request(maxChunks?: number) {
  const pipeline = { ...google_calendarPipeline, retry: { retries: 0 }, streams: google_calendarPipeline.streams.map((stream) => ({ ...stream, ...(maxChunks === undefined ? {} : { budget: { maxChunks } }) })) }
  return { selected: selectStreams([pipeline], []), backfill: undefined }
}

afterEach(() => {
  globalThis.fetch = originalFetch
  if (originalToken === undefined) delete process.env.GOOGLE_CALENDAR_ACCESS_TOKEN
  else process.env.GOOGLE_CALENDAR_ACCESS_TOKEN = originalToken
})

test.serial('Calendar resumes an acknowledged page and promotes only the terminal sync token', async () => {
  const urls: URL[] = []
  setFetch((url) => {
    urls.push(url)
    return Response.json(url.searchParams.has('pageToken')
      ? { items: [{ id: 'cancelled', status: 'cancelled' }], nextSyncToken: 'sync-1' }
      : { items: [{ id: 'series', recurrence: ['RRULE:FREQ=WEEKLY'] }], nextPageToken: 'next' })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const interrupted = await runIngestion(request(1), { journal, destination })
  expect(interrupted.streams[0]?.outcome).toBe('budget_exhausted')
  expect((await journal.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ pageToken: 'next' })
  const resumed = await runIngestion(request(), { journal, destination })
  expect(resumed.ok).toBe(true)
  expect(urls.map((url) => url.searchParams.get('pageToken'))).toEqual([null, 'next'])
  expect((await journal.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ syncToken: 'sync-1', calendarId: 'calendar@example.com' })
  expect(destination.tables.get('default.google_calendar_events_raw')?.map((row) => row.raw)).toEqual([
    { id: 'series', recurrence: ['RRULE:FREQ=WEEKLY'] }, { id: 'cancelled', status: 'cancelled' },
  ])
  for (const url of urls) {
    expect(url.searchParams.get('singleEvents')).toBe('false')
    expect(url.searchParams.get('showDeleted')).toBe('true')
    expect(url.searchParams.has('timeMin')).toBe(false)
    expect(url.searchParams.has('timeMax')).toBe(false)
  }
})

test.serial('Calendar keeps the input sync token across empty delta pages', async () => {
  let bootstrap = true
  const inputs: Array<string | null> = []
  setFetch((url) => {
    inputs.push(url.searchParams.get('syncToken'))
    if (bootstrap) return Response.json({ items: [], nextSyncToken: 'sync-1' })
    return Response.json(url.searchParams.has('pageToken')
      ? { items: [], nextSyncToken: 'sync-2' }
      : { items: [], nextPageToken: 'delta-next' })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(), { journal, destination })).ok).toBe(true)
  bootstrap = false
  expect((await runIngestion(request(), { journal, destination })).ok).toBe(true)
  expect(inputs).toEqual([null, 'sync-1', 'sync-1'])
  expect((await journal.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ syncToken: 'sync-2' })
})

test('Calendar preserves native event structure and replaces an exception with its sparse cancellation', async () => {
  const series = {
    id: 'series', status: 'confirmed', recurrence: ['RRULE:FREQ=WEEKLY'],
    attendees: [{ email: 'guest@example.com', responseStatus: 'accepted' }],
    organizer: { email: 'owner@example.com' }, reminders: { useDefault: false, overrides: [{ method: 'email', minutes: 30 }] },
    conferenceData: { conferenceId: 'abc-defg-hij', entryPoints: [{ entryPointType: 'video', uri: 'https://meet.google.com/abc-defg-hij' }] },
    attachments: [{ fileId: 'file-1', fileUrl: 'https://drive.google.com/file/d/file-1/view' }],
    extendedProperties: { private: { custom: 'retained' } },
  }
  const exception = { id: 'exception', recurringEventId: series.id, originalStartTime: { dateTime: '2026-10-06T09:00:00Z' }, summary: 'Moved occurrence' }
  const cancellation = { id: exception.id, status: 'cancelled', recurringEventId: series.id, originalStartTime: exception.originalStartTime }
  const calls: URL[] = []
  const pipeline = createGoogleCalendarPipeline(googleCalendarConfig, {
    config: googleCalendarConfig,
    token: () => 'fixture',
    fetch: async (input) => {
      const url = new URL(input)
      calls.push(url)
      return Response.json(url.pathname.endsWith('/events')
        ? url.searchParams.has('syncToken') ? { items: [cancellation], nextSyncToken: 'sync-2' } : { items: [series, exception], nextSyncToken: 'sync-1' }
        : { id: 'calendar@example.com' })
    },
  })
  const journal = createMemoryJournal(), destination = createMemoryDestination()
  const input = { selected: selectStreams([pipeline], ['resource:events']), backfill: undefined }
  expect((await runIngestion(input, { journal, destination })).ok).toBe(true)
  expect(destination.tables.get('default.google_calendar_events_raw')?.map((row) => row.raw)).toEqual([series, exception])
  expect((await runIngestion(input, { journal, destination })).ok).toBe(true)
  const latest = new Map(destination.tables.get('default.google_calendar_events_raw')?.map((row) => [row.id, row.raw]))
  expect(latest.size).toBe(2)
  expect(latest.get(JSON.stringify(['google-calendar.primary', 'calendar@example.com', exception.id]))).toEqual(cancellation)
  expect(calls.filter((url) => url.pathname.endsWith('/events')).map((url) => url.searchParams.get('syncToken'))).toEqual([null, 'sync-1'])
  expect(calls).toHaveLength(4)
})

test.serial('Calendar retains its page checkpoint after a lost terminal acknowledgement', async () => {
  setFetch((url) => Response.json(url.searchParams.has('pageToken')
    ? { items: [{ id: 'second' }], nextSyncToken: 'sync-1' }
    : { items: [{ id: 'first' }], nextPageToken: 'next' }))
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const first = await runIngestion(request(), { journal, destination: {
    insert: async (input) => {
      await destination.insert(input)
      if (input.rows.some((row) => JSON.stringify(row.raw).includes('second'))) throw new Error('fixture acknowledgement lost')
    },
  } })
  expect(first.ok).toBe(false)
  expect(destination.tables.get('default.google_calendar_events_raw')).toHaveLength(2)
  expect((await journal.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ pageToken: 'next' })
  expect((await runIngestion(request(), { journal, destination })).ok).toBe(true)
  expect((await journal.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ syncToken: 'sync-1' })
  expect(destination.tables.get('default.google_calendar_events_raw')).toHaveLength(2)
})

test.serial('Calendar reboots an expired sync without deleting raw observations', async () => {
  let changed = false
  const inputs: Array<string | null> = []
  setFetch((url) => {
    inputs.push(url.searchParams.get('syncToken'))
    if (!changed) return Response.json({ items: [{ id: 'old' }], nextSyncToken: 'expired' })
    return url.searchParams.has('syncToken') ? new Response('expired', { status: 410 }) : Response.json({ items: [], nextSyncToken: 'fresh' })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(), { journal, destination })).ok).toBe(true)
  changed = true
  expect((await runIngestion(request(), { journal, destination })).ok).toBe(true)
  expect(inputs).toEqual([null, 'expired', null])
  expect(destination.tables.get('default.google_calendar_events_raw')).toHaveLength(1)
  expect((await journal.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ syncToken: 'fresh' })
})

test.serial('Calendar rejects malformed terminal pages and repeated page tokens', async () => {
  setFetch(() => Response.json({ items: [] }))
  expect((await runIngestion(request(), { journal: createMemoryJournal(), destination: createMemoryDestination() })).ok).toBe(false)
  setFetch(() => Response.json({ items: [], nextPageToken: 'same' }))
  expect((await runIngestion(request(), { journal: createMemoryJournal(), destination: createMemoryDestination() })).ok).toBe(false)
  expect(() => google_calendarPipeline.streams[0]?.incremental.parseState({ scope: 'another source' })).toThrow('scope')
})

test.serial('Calendar refuses to reuse a checkpoint after primary changes accounts', async () => {
  let calendar = 'first@example.com'
  let eventRequests = 0
  setFetch(() => { eventRequests += 1; return Response.json({ items: [], nextSyncToken: 'sync-1' }) }, () => calendar)
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(), { journal, destination })).ok).toBe(true)
  calendar = 'second@example.com'
  const result = await runIngestion(request(), { journal, destination })
  expect(result.ok).toBe(false)
  expect(result.streams[0]?.error).toContain('different authenticated calendar')
  expect(eventRequests).toBe(1)
})

test.serial('Calendar safely restarts a rejected page token within the same sync', async () => {
  let reject = true
  const inputs: Array<string | null> = []
  setFetch((url) => {
    inputs.push(url.searchParams.get('pageToken'))
    if (url.searchParams.has('pageToken') && reject) { reject = false; return new Response('invalid page token', { status: 400 }) }
    return Response.json(url.searchParams.has('pageToken')
      ? { items: [], nextSyncToken: 'sync-1' }
      : { items: [{ id: 'first' }], nextPageToken: 'next' })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(), { journal, destination })).ok).toBe(true)
  expect(inputs).toEqual([null, 'next', null, 'next'])
  expect(new Set(destination.tables.get('default.google_calendar_events_raw')?.map((row) => row.id)).size).toBe(1)
  expect((await journal.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ syncToken: 'sync-1' })
})

test.serial('Calendar rejects unsupported explicit occurrence backfill bounds before requesting Google', async () => {
  let requested = false
  setFetch(() => { requested = true; return Response.json({ items: [], nextSyncToken: 'sync-1' }) })
  const result = await runIngestion({ ...request(), backfill: { id: 'dates', from: new Date('2026-10-01T00:00:00Z'), to: new Date('2026-10-05T00:00:00Z') } }, { journal: createMemoryJournal(), destination: createMemoryDestination() })
  expect(result.ok).toBe(false)
  expect(result.streams[0]?.error).toContain('does not accept date bounds')
  expect(requested).toBe(false)
})

test.serial('Calendar carries reset debt through serialized fresh runs and successful nonterminal replay', async () => {
  let rejected = 0
  setFetch((url) => {
    if (url.searchParams.has('pageToken')) { rejected += 1; return new Response('expired page token', { status: 400 }) }
    return Response.json({ items: [{ id: 'first' }], nextPageToken: 'next' })
  })
  const destination = createMemoryDestination()
  const initial = createMemoryJournal()
  expect((await runIngestion(request(1), { journal: initial, destination })).streams[0]?.outcome).toBe('budget_exhausted')
  const afterInitial = restoredJournal(initial)
  expect((await runIngestion(request(1), { journal: afterInitial, destination })).streams[0]?.outcome).toBe('budget_exhausted')
  expect((await afterInitial.readCheckpoint('google-calendar.events')).envelope?.state).toMatchObject({ recoveryCount: 1 })
  expect((await afterInitial.readCheckpoint('google-calendar.events')).envelope?.state).not.toHaveProperty('pageToken')
  const afterReset = restoredJournal(afterInitial)
  expect((await runIngestion(request(1), { journal: afterReset, destination })).streams[0]?.outcome).toBe('budget_exhausted')
  const replayCheckpoint = await afterReset.readCheckpoint('google-calendar.events')
  expect(replayCheckpoint.envelope?.state).toMatchObject({ recoveryCount: 1, pageToken: 'next' })
  const afterReplay = restoredJournal(afterReset)
  const stopped = await runIngestion(request(2), { journal: afterReplay, destination })
  expect(stopped.ok).toBe(false)
  expect(stopped.streams[0]?.error).toContain('across resumed runs')
  expect(stopped.streams[0]?.error).toContain('editable stream chunk budget')
  expect((await afterReplay.readCheckpoint('google-calendar.events')).version).toBe(replayCheckpoint.version)
  expect(rejected).toBe(2)
  expect(() => google_calendarPipeline.streams[0]?.incremental.parseState({ ...JSON.parse(JSON.stringify(replayCheckpoint.envelope?.state)), recoveryCount: 2 })).toThrow('recoveryCount')
})

function restoredJournal(previous: ReturnType<typeof createMemoryJournal>) {
  const journal = createMemoryJournal()
  journal.events.push(...previous.events.map((event) => ({ ...event, checkpoint: event.checkpoint === undefined ? undefined : JSON.parse(JSON.stringify(event.checkpoint)) })))
  return journal
}

test('Calendar factory snapshots installation settings and injected credentials while resuming an empty terminal page', async () => {
  const config = { ...googleCalendarConfig, sourceId: 'calendar.work', streamPrefix: 'calendar.work', calendarId: 'work', maxChunks: 1 }
  let token = 'initial'
  const requests: Array<{ url: URL; authorization: string | null }> = []
  const deps = {
    config: googleCalendarConfig,
    token: () => token,
    fetch: async (input: string, init: RequestInit) => {
      const url = new URL(input)
      requests.push({ url, authorization: new Headers(init.headers).get('Authorization') })
      return Response.json(url.pathname.endsWith('/events')
        ? url.searchParams.has('pageToken')
          ? { items: [], nextSyncToken: 'work-sync' }
          : { items: [{ id: 'first', custom: { original: true } }], nextPageToken: 'work-next' }
        : { id: 'work@example.com' })
    },
  }
  const pipeline = createGoogleCalendarPipeline(config, deps)
  config.sourceId = 'edited-after-construction'
  config.streamPrefix = 'edited-after-construction'
  config.calendarId = 'edited-after-construction'
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect(pipeline.id).toBe('calendar.work')
  expect(pipeline.streams[0]?.incremental.id).toBe('calendar.work.sync-token')
  expect((await runIngestion({ selected: selectStreams([pipeline], ['resource:events']), backfill: undefined }, { journal, destination })).streams[0]?.outcome).toBe('budget_exhausted')
  expect((await journal.readCheckpoint('calendar.work.events')).envelope?.state).toMatchObject({ pageToken: 'work-next' })
  token = 'rotated'
  const resumed = { ...pipeline, streams: pipeline.streams.map((stream) => ({ ...stream, budget: { ...stream.budget, maxChunks: 20 } })) }
  expect((await runIngestion({ selected: selectStreams([resumed], []), backfill: undefined }, { journal, destination })).ok).toBe(true)
  expect(requests.map(({ authorization }) => authorization)).toEqual(['Bearer initial', 'Bearer initial', 'Bearer rotated', 'Bearer rotated'])
  expect(requests.map(({ url }) => [url.pathname, url.searchParams.get('pageToken')])).toEqual([
    ['/calendar/v3/calendars/work', null], ['/calendar/v3/calendars/work%40example.com/events', null],
    ['/calendar/v3/calendars/work', null], ['/calendar/v3/calendars/work%40example.com/events', 'work-next'],
  ])
  expect((await journal.readCheckpoint('calendar.work.events')).envelope?.state).toMatchObject({ syncToken: 'work-sync' })
  expect((await journal.readCheckpoint('google-calendar.events')).version).toBe(0)
  expect(destination.tables.get('default.google_calendar_events_raw')?.[0]).toMatchObject({
    id: JSON.stringify(['calendar.work', 'work@example.com', 'first']), raw: { id: 'first', custom: { original: true } },
  })
})

test('Calendar factory rejects source changes under an existing stream prefix before another request', async () => {
  let requests = 0
  const deps = {
    config: googleCalendarConfig, token: () => 'fixture',
    fetch: async (input: string) => {
      requests += 1
      return Response.json(new URL(input).pathname.endsWith('/events') ? { items: [], nextSyncToken: 'first' } : { id: 'calendar@example.com' })
    },
  }
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const pipeline = createGoogleCalendarPipeline(googleCalendarConfig, deps)
  expect((await runIngestion({ selected: selectStreams([pipeline], []), backfill: undefined }, { journal, destination })).ok).toBe(true)
  const changed = createGoogleCalendarPipeline({ ...googleCalendarConfig, sourceId: 'different-installation' }, deps)
  const result = await runIngestion({ selected: selectStreams([changed], []), backfill: undefined }, { journal, destination })
  expect(result.ok).toBe(false)
  expect(result.streams[0]?.error).toContain('scope changed')
  expect(requests).toBe(2)
})
